const BASE='https://mabvxdcpmfdzrqlgkxqn.supabase.co';
const KEY='sb_publishable_Fh0fWwz6kCfMlcgYCsTJOA_eZmHsib4';
const API=BASE+'/functions/v1/v1-runtime';
const params=new URLSearchParams(location.search);
if(params.get('group_invite'))sessionStorage.setItem('dp_group_invite',params.get('group_invite'));
if(params.get('ref'))sessionStorage.setItem('dp_referral',params.get('ref'));
const state={session:readSession(),me:null,overview:null,mySpace:null,enterprise:null,context:sessionStorage.getItem('dp_context')||'',page:'home',detail:null,invite:sessionStorage.getItem('dp_invite')||'',groupInvite:sessionStorage.getItem('dp_group_invite')||'',referral:sessionStorage.getItem('dp_referral')||'',busy:false,sessionExpired:false};
const $=s=>document.querySelector(s);
const esc=x=>String(x??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const fmt=d=>d?new Intl.DateTimeFormat('ko-KR',{year:'numeric',month:'short',day:'numeric'}).format(new Date(d)):'미정';
const labels={ACTIVE:'진행 중',DRAFT:'준비 중',OPEN:'모집 중',SUBMITTED:'접수',APPROVED:'승인',STARTED:'참여 중',COMPLETED:'완료',CONNECTED:'연결 완료',SELECTED:'연결 가능',REVIEWING:'검토 중',PENDING:'대기',VERIFIED:'인증 완료',OWNER:'운영자',MEMBER:'구성원',OWNER_VET:'원장',DIRECTOR:'원장',VETERINARIAN:'수의사',VET:'수의사',STAFF:'직원',STUDENT:'수의대생',ENTERPRISE_USER:'기업회원',GUARDIAN:'보호자',ADMIN:'관리자',GENERAL:'일반 지원',PRODUCT:'제품·샘플',DEMO:'장비 데모',SPONSORSHIP:'협찬·스폰서십',MANAGEMENT:'경영·운영 지원'};
const label=x=>labels[x]||x||'-';
function readSession(){try{return JSON.parse(sessionStorage.getItem('dp_session')||'null')}catch{return null}}
class ClientError extends Error{constructor(status,code,message){super(message);this.status=status;this.code=code}}
async function auth(path,body){const r=await fetch(BASE+'/auth/v1/'+path,{method:'POST',headers:{apikey:KEY,'content-type':'application/json'},body:JSON.stringify(body)});const j=await r.json();if(!r.ok)throw new ClientError(r.status,j.error||'',j.msg||j.error_description||j.message||'인증에 실패했습니다.');return j}
async function api(path,{method='GET',body,idempotency}={}){const r=await fetch(API+path,{method,headers:{authorization:'Bearer '+state.session?.access_token,apikey:KEY,'content-type':'application/json','x-request-id':crypto.randomUUID(),...(idempotency?{'x-idempotency-key':idempotency}:{})},body:body?JSON.stringify(body):undefined});let j={};try{j=await r.json()}catch{}if(!r.ok){if(r.status===401)expireSession();throw new ClientError(r.status,j.error?.code||'',j.error?.message||'요청을 처리하지 못했습니다.')}return j.data}
function expireSession(){sessionStorage.removeItem('dp_session');state.session=null;state.me=null;state.overview=null;state.sessionExpired=true}
function setMsg(m,ok=false){const e=$('#msg');if(e){e.className=ok?'notice success':'notice error';e.textContent=m}}
function badge(value){return `<span class="badge badge-${esc(String(value||'').toLowerCase())}">${esc(label(value))}</span>`}
function empty(title,body='새로운 내용이 생기면 이곳에 표시됩니다.'){return `<div class="empty"><div class="empty-icon">＋</div><strong>${esc(title)}</strong><p>${esc(body)}</p></div>`}
function loading(){return `<div class="loading"><span></span><p>정보를 불러오는 중입니다.</p></div>`}
function errorView(x){const denied=x?.status===403;return `<div class="state-panel ${denied?'deny':'error'}"><strong>${denied?'접근 권한이 없습니다':'정보를 불러오지 못했습니다'}</strong><p>${esc(denied?'현재 역할과 소속으로 허용되지 않은 기능입니다.':x?.message||'잠시 후 다시 시도해 주세요.')}</p><button class="secondary" data-retry>다시 시도</button></div>`}
async function login(e){e.preventDefault();setMsg('');try{const d=await auth('token?grant_type=password',{email:$('#email').value,password:$('#password').value});state.session=d;state.sessionExpired=false;sessionStorage.setItem('dp_session',JSON.stringify(d));await load()}catch(x){setMsg(x.message)}}
async function signup(e){e.preventDefault();try{const d=await auth('signup',{email:$('#email').value,password:$('#password').value,data:{display_name:$('#name').value}});if(!d.access_token)throw new Error('이메일 확인 후 로그인해 주세요.');state.session=d;sessionStorage.setItem('dp_session',JSON.stringify(d));const b=await api('/profile/bootstrap',{method:'POST',body:{displayName:$('#name').value,role:$('#role').value}});state.invite=b.invitationToken||'';sessionStorage.setItem('dp_invite',state.invite);await load()}catch(x){setMsg(x.message)}}
async function activate(){try{await api('/activation',{method:'POST',body:{invitationToken:state.invite},idempotency:'activate:'+state.session.user.id});await load()}catch(x){setMsg(x.message)}}
async function logout(){try{await auth('logout',{})}catch{}sessionStorage.clear();state.session=null;state.me=null;state.overview=null;state.enterprise=null;state.sessionExpired=false;state.page='home';render()}
async function load(){state.busy=true;render();try{state.me=await api('/me');if(state.me?.state==='ACTIVE'){const enterpriseAff=primaryEnterprise();if(!state.context)state.context=enterpriseAff&&!isHospitalUser()?'enterprise':'hospital';[state.overview,state.mySpace,state.enterprise]=await Promise.all([api('/overview'),api('/my-space'),enterpriseAff?api('/enterprises/'+enterpriseAff.enterprise_id+'/overview'):Promise.resolve(null)])}else{state.overview=null;state.mySpace=null;state.enterprise=null}state.busy=false;render()}catch(x){state.busy=false;if(!state.session)return render();state.me=null;render(errorView(x))}}
async function refreshOverview(){state.busy=true;render();try{state.overview=await api('/overview');state.busy=false;render()}catch(x){state.busy=false;render(errorView(x))}}
async function refreshMySpace(){state.mySpace=await api('/my-space');state.detail=null;render()}
function authView(){return `<div class="auth-wrap"><div class="auth-card"><div class="logo-mark">D</div><div class="brand auth-brand">DoctorPet</div><h1>병원 네트워크 로그인</h1><p class="muted">동물병원 캠페인과 무료지원 서비스를 이용하세요.</p>${state.sessionExpired?'<div class="notice error">로그인이 만료되었습니다. 다시 로그인해 주세요.</div>':''}<div id="msg"></div><form id="login"><label>이메일<input id="email" type="email" autocomplete="username" placeholder="이메일 주소" required></label><label>비밀번호<input id="password" type="password" autocomplete="current-password" minlength="10" placeholder="비밀번호" required></label><button class="primary full-button" type="submit">로그인</button></form><details class="dev-signup"><summary>DEV 테스트 회원가입</summary><form id="signup"><input id="name" placeholder="이름" required><select id="role"><option>VET</option><option>STAFF</option><option>STUDENT</option><option>ENTERPRISE_USER</option><option>GUARDIAN</option></select><button class="secondary" type="submit">가입하기</button></form></details></div></div>`}
const hospitalNav=[['home','홈','⌂'],['hospital','내 병원','✚'],['campaign','캠페인','▣'],['support','무료지원','♡'],['matching','매칭','⇄'],['space','내 공간','⌘'],['account','내 계정','○'],['more','더보기','•••']];
const enterpriseNav=[['home','홈','⌂'],['enterprise','기업방','▦'],['campaign','캠페인','▣'],['matching','병원 매칭','⇄'],['partnership','제휴·광고','◇'],['space','내 공간','⌘'],['account','내 계정','○'],['more','더보기','•••']];
const legacyNav=[['home','홈','⌂'],['hospital','병원방','✚'],['enterprise','기업방','▦'],['campaign','캠페인','▣'],['support','무료지원','♡'],['matching','매칭','⇄'],['admin','관리자','◇']];
function isHospitalUser(){return state.me?.roles?.includes('VET')||state.me?.affiliations?.some(a=>a.organization_type==='HOSPITAL')}
function isEnterpriseUser(){return state.me?.roles?.includes('ENTERPRISE_USER')||state.me?.affiliations?.some(a=>a.organization_type==='ENTERPRISE')}
function isEnterpriseContext(){return isEnterpriseUser()&&(!isHospitalUser()||state.context==='enterprise')}
function navItems(){return isEnterpriseContext()?enterpriseNav:isHospitalUser()?hospitalNav:legacyNav}
function shell(content){const items=navItems(),multi=isHospitalUser()&&isEnterpriseUser();return `<div class="shell ${isEnterpriseContext()?'enterprise-shell':''}"><header class="top"><div class="top-brand"><span class="logo-mark small">D</span><span class="brand">DoctorPet</span><span class="dev-tag">DEV</span></div><div class="profile-chip">${multi?`<button class="context-switch" id="contextSwitch">${isEnterpriseContext()?'병원 공간으로':'기업 공간으로'}</button>`:''}<span>${esc(state.me?.profile?.display_name||'회원')}</span>${badge(state.me?.state)}</div></header><div class="layout"><nav class="nav" aria-label="주 메뉴">${items.map(([k,v,i])=>`<button data-page="${k}" class="${state.page===k?'active':''}"><span>${i}</span>${v}</button>`).join('')}</nav><main class="main">${content}</main></div></div>`}
function pageTitle(title,desc,action=''){return `<div class="page-head"><div><h1>${esc(title)}</h1><p>${esc(desc)}</p></div>${action}</div>`}
function metric(title,value,note,page){return `<button class="metric-card" ${page?`data-page="${page}"`:''}><span>${esc(title)}</span><strong>${esc(value)}</strong><small>${esc(note)}</small></button>`}
function primaryHospital(){return state.me?.affiliations?.find(a=>a.organization_type==='HOSPITAL'&&a.status==='ACTIVE'&&a.verification_status==='VERIFIED'&&a.is_primary)||state.me?.affiliations?.find(a=>a.organization_type==='HOSPITAL'&&a.status==='ACTIVE'&&a.verification_status==='VERIFIED')}
function primaryEnterprise(){return state.me?.affiliations?.find(a=>a.organization_type==='ENTERPRISE'&&a.status==='ACTIVE'&&a.verification_status==='VERIFIED'&&a.is_primary)||state.me?.affiliations?.find(a=>a.organization_type==='ENTERPRISE'&&a.status==='ACTIVE'&&a.verification_status==='VERIFIED')}
function applicationFor(campaignId){return state.overview?.applications?.find(a=>a.campaign_id===campaignId)}
function hospitalHome(){const hospital=primaryHospital();const open=(state.overview?.campaigns||[]).filter(c=>c.status==='OPEN');const applications=state.overview?.applications||[];const participations=applications.filter(a=>a.participation_status);const support=state.overview?.support||[];const matched=(state.overview?.matching||[]).filter(m=>m.result_status==='CONNECTED'||m.status==='COMPLETED');const alerts=[applications[0]&&`최근 캠페인 신청은 ${label(applications[0].participation_status||applications[0].status)} 상태입니다.`,support[0]&&`무료지원 요청이 ${label(support[0].status)} 상태입니다.`,matched[0]&&`${matched[0].enterprise_name||'파트너 기업'} 매칭 결과를 확인해 주세요.`].filter(Boolean);return `${pageTitle('안녕하세요, '+(state.me.profile?.display_name||'원장님')+'님','오늘의 병원 운영 현황을 한눈에 확인하세요.')}<section class="hospital-hero"><div><span class="eyebrow">내 병원</span><h2>${esc(hospital?.name||'소속 병원 확인 필요')}</h2><p>${hospital?`${esc(label(hospital.position_code||'소속'))} · ${esc(label(hospital.verification_status))}`:'인증된 병원 소속이 없습니다.'}</p></div><button class="light-button" data-page="hospital">병원 정보 보기 →</button></section><div class="metrics five">${metric('진행 캠페인',open.length+'건','신청 가능한 캠페인','campaign')}${metric('내 신청',applications.length+'건',applications[0]?label(applications[0].status):'신청 내역 없음','campaign')}${metric('참여 현황',participations.length+'건',participations[0]?label(participations[0].participation_status):'참여 전','campaign')}${metric('무료지원',support.length+'건',support[0]?label(support[0].status):'요청 내역 없음','support')}${metric('매칭 결과',matched.length+'건',matched[0]?label(matched[0].result_status):'매칭 대기','matching')}</div><section class="section"><div class="section-head"><h2>주요 알림</h2></div>${alerts.length?`<div class="alert-list">${alerts.map(x=>`<div><span>●</span>${esc(x)}</div>`).join('')}</div>`:empty('새로운 알림이 없습니다.','캠페인 신청과 지원 요청의 진행 소식을 알려드립니다.')}</section><section class="section"><div class="section-head"><h2>빠른 시작</h2></div><div class="quick-grid"><button data-page="campaign"><b>캠페인 찾기</b><span>병원에 맞는 캠페인 확인</span></button><button data-page="support"><b>무료지원 요청</b><span>제품·샘플·데모 지원 신청</span></button><button data-page="matching"><b>매칭 현황</b><span>연결된 기업과 진행상태 확인</span></button></div></section>`}
function hospitalPage(){const affiliations=(state.me.affiliations||[]).filter(a=>a.organization_type==='HOSPITAL');const rooms=(state.me.rooms||[]).filter(r=>r.room_type?.includes('HOSPITAL'));return `${pageTitle('내 병원','인증된 소속과 병원 전용 공간을 확인합니다.')}<div class="content-grid"><section class="panel"><div class="section-head"><h2>병원·소속 정보</h2>${affiliations[0]?badge(affiliations[0].verification_status):''}</div>${affiliations.length?affiliations.map(a=>`<article class="info-card"><div><span class="eyebrow">${a.is_primary?'대표 소속':'소속 병원'}</span><h3>${esc(a.name)}</h3></div><dl><div><dt>현재 역할</dt><dd>${esc(label(a.position_code||'소속 구성원'))}</dd></div><div><dt>지역</dt><dd>${esc(a.region_code||'정보 없음')}</dd></div><div><dt>소속 상태</dt><dd>${badge(a.status)}</dd></div><div><dt>인증 상태</dt><dd>${badge(a.verification_status)}</dd></div></dl></article>`).join(''):empty('인증된 병원 소속이 없습니다.')}</section><section class="panel"><div class="section-head"><h2>병원방</h2><span>${rooms.length}개</span></div>${rooms.length?`<div class="stack">${rooms.map(r=>`<button class="list-card" data-room="${esc(r.id)}"><span class="list-icon">병</span><span><b>${esc(primaryHospital()?.name||'병원')} 전용 공간</b><small>${esc(label(r.membership_role))} · ${label(r.status)}</small></span><i>›</i></button>`).join('')}</div>`:empty('참여 중인 병원방이 없습니다.')}</section></div><section class="panel permissions"><div class="section-head"><h2>현재 역할</h2></div><div class="chip-row">${(state.me.roles||[]).map(x=>`<span class="role-chip">${esc(label(x))}</span>`).join('')}</div><div class="slot-row"><div><b>병원 구성원과 권한</b><p>구성원 관리 화면은 다음 단계에서 연결됩니다.</p></div><span class="slot-badge">준비 중</span></div></section>`}
function roomDetailView(room){return `${pageTitle('병원방 상세','내 소속과 역할에 따라 이용할 수 있는 병원 전용 공간입니다.','<button class="secondary" data-page="hospital">← 목록</button>')}<section class="panel detail-panel"><span class="eyebrow">병원 전용 공간</span><h2>${esc(primaryHospital()?.name||'병원방')}</h2><p class="lead">캠페인, 무료지원과 매칭 현황을 병원 구성원과 함께 확인하는 공간입니다.</p><dl><div><dt>공간</dt><dd>병원방</dd></div><div><dt>내 역할</dt><dd>${esc(label(room.membership_role))}</dd></div><div><dt>이용 상태</dt><dd>${badge(room.status)}</dd></div></dl><div class="quick-grid compact"><button data-page="campaign"><b>캠페인</b><span>신청과 참여 현황</span></button><button data-page="support"><b>무료지원</b><span>요청과 진행상태</span></button><button data-page="matching"><b>매칭</b><span>기업 연결 결과</span></button></div></section>`}
function campaignCard(c){const a=applicationFor(c.id);return `<article class="campaign-card"><div class="campaign-top"><span class="eyebrow">${esc(c.enterprise_name||'파트너 기업')}</span>${badge(c.status)}</div><h3>${esc(c.name)}</h3><p>${esc(typeof c.brief==='object'?(c.brief?.summary||c.brief?.description||'동물병원을 위한 캠페인입니다.'):(c.brief||'동물병원을 위한 캠페인입니다.'))}</p><div class="date-row"><span>${fmt(c.starts_at)} 시작</span><span>${c.ends_at?fmt(c.ends_at)+' 종료':'종료일 미정'}</span></div><div class="card-actions">${a?`<span class="application-state">${label(a.participation_status||a.status)}</span>`:''}<button class="secondary" data-campaign="${esc(c.id)}">상세 보기</button></div></article>`}
function campaignsPage(){const rows=state.overview?.campaigns||[];return `${pageTitle('동물병원 캠페인','병원에 맞는 캠페인을 확인하고 바로 신청하세요.')}<div class="filter-row"><button class="filter active">전체 ${rows.length}</button><button class="filter">진행 중 ${rows.filter(x=>x.status==='OPEN').length}</button><span class="spacer"></span><span class="muted">내 신청 ${(state.overview?.applications||[]).length}건</span></div>${rows.length?`<div class="campaign-grid">${rows.map(campaignCard).join('')}</div>`:empty('현재 진행 중인 캠페인이 없습니다.')}`}
function campaignDetail(c){const a=applicationFor(c.id);const canApply=c.status==='OPEN'&&!a;const brief=typeof c.brief==='object'?c.brief:{};return `${pageTitle('캠페인 상세','신청 조건과 진행상태를 확인하세요.','<button class="secondary" data-page="campaign">← 목록</button>')}<article class="panel detail-panel"><div class="campaign-top"><span class="eyebrow">${esc(c.enterprise_name||'파트너 기업')}</span>${badge(c.status)}</div><h2>${esc(c.name)}</h2><p class="lead">${esc(typeof c.brief==='object'?(brief.summary||brief.description||'등록된 상세 설명이 없습니다.'):(c.brief||'등록된 상세 설명이 없습니다.'))}</p><dl><div><dt>캠페인 유형</dt><dd>${esc(labels[c.campaign_type]||'동물병원 캠페인')}</dd></div><div><dt>진행 기간</dt><dd>${fmt(c.starts_at)} — ${c.ends_at?fmt(c.ends_at):'미정'}</dd></div><div><dt>참여 대상</dt><dd>${esc(brief.target||'참여 가능한 동물병원')}</dd></div><div><dt>제공 혜택</dt><dd>${esc(brief.benefit||brief.benefits||'캠페인 상세 혜택을 확인해 주세요.')}</dd></div><div><dt>신청 상태</dt><dd>${a?badge(a.status):'미신청'}</dd></div><div><dt>참여 상태</dt><dd>${a?.participation_status?badge(a.participation_status):'참여 전'}</dd></div></dl><div class="detail-action">${canApply?`<button class="primary" id="applyCampaign" data-id="${esc(c.id)}">이 캠페인 신청하기</button>`:a?`<div class="notice success">신청이 접수되었습니다. 현재 상태: ${esc(label(a.participation_status||a.status))}</div>`:`<div class="notice">현재 신청할 수 없는 캠페인입니다.</div>`}</div></article>`}
function supportPage(){const hospital=primaryHospital();const rows=state.overview?.support||[];return `${pageTitle('동물병원 무료지원센터','제품·샘플·데모·운영 지원을 요청하세요.')}<div class="content-grid support-layout"><section class="panel form-panel"><div class="section-head"><h2>새 지원 요청</h2></div>${hospital?`<div class="selected-hospital"><span>신청 병원</span><b>${esc(hospital.name)}</b>${badge(hospital.verification_status)}</div><form id="supportForm"><label>지원 유형<select id="supportType"><option value="GENERAL">일반 지원</option><option value="PRODUCT">제품·샘플</option><option value="DEMO">장비 데모</option><option value="SPONSORSHIP">협찬·스폰서십</option><option value="MANAGEMENT">경영·운영 지원</option></select></label><label>요청 제목<input id="supportTitle" maxlength="120" placeholder="필요한 지원을 한 줄로 입력하세요" required></label><label>요청 내용<textarea id="supportDesc" maxlength="1000" rows="6" placeholder="필요한 제품, 수량, 일정 등을 알려주세요" required></textarea></label><button class="primary full-button" type="submit">지원 요청 등록</button></form>`:`<div class="state-panel deny"><strong>인증된 병원 소속이 필요합니다.</strong><p>병원 소속 인증이 완료되면 무료지원을 요청할 수 있습니다.</p></div>`}</section><section class="panel"><div class="section-head"><h2>내 요청 현황</h2><span>${rows.length}건</span></div>${rows.length?`<div class="stack">${rows.map(r=>`<button class="list-card support-card" data-support="${esc(r.id)}"><span><b>${esc(r.title||r.request_type)}</b><small>${fmt(r.requested_at)} · ${esc(label(r.request_type))}</small></span>${badge(r.status)}<i>›</i></button>`).join('')}</div>`:empty('아직 등록한 지원 요청이 없습니다.','첫 지원 요청을 작성하면 진행상태를 이곳에서 확인할 수 있습니다.')}</section></div>`}
function supportDetail(r){const match=(state.overview?.matching||[]).find(m=>m.support_request_id===r.id);return `${pageTitle('지원 요청 상세','요청 내용과 매칭 진행상태입니다.','<button class="secondary" data-page="support">← 목록</button>')}<section class="panel detail-panel"><div class="campaign-top"><span class="eyebrow">${esc(label(r.request_type))}</span>${badge(r.status)}</div><h2>${esc(r.title||'지원 요청')}</h2><p class="lead">${esc(r.description||'등록된 상세 내용이 없습니다.')}</p><dl><div><dt>신청 병원</dt><dd>${esc(primaryHospital()?.name||'-')}</dd></div><div><dt>신청일</dt><dd>${fmt(r.requested_at)}</dd></div><div><dt>매칭 상태</dt><dd>${match?badge(match.status):'매칭 대기'}</dd></div></dl>${match?`<button class="secondary" data-page="matching">매칭 결과 보기 →</button>`:''}</section>`}
function matchingPage(){const rows=state.overview?.matching||[];return `${pageTitle('기업 매칭','지원 요청별 기업 연결 결과를 확인하세요.')}<section class="panel"><div class="section-head"><h2>매칭 현황</h2><span>${rows.length}건</span></div>${rows.length?`<div class="stack">${rows.map(m=>`<button class="matching-card" data-matching="${esc(m.id)}"><span class="match-flow"><i>요청</i><em></em><i>매칭</i><em></em><i class="${m.result_status==='CONNECTED'?'done':''}">연결</i></span><span class="match-copy"><b>${esc(m.support_title||'지원 요청')}</b><small>${esc(m.enterprise_name||'기업 검토 중')} · ${fmt(m.opened_at)}</small></span>${badge(m.result_status||m.status)}<strong>›</strong></button>`).join('')}</div>`:empty('진행 중인 매칭이 없습니다.','무료지원 요청이 접수되면 매칭 진행상태가 표시됩니다.')}</section>`}
function matchingDetail(m){return `${pageTitle('매칭 상세','지원 요청과 연결 기업의 현재 상태입니다.','<button class="secondary" data-page="matching">← 목록</button>')}<section class="panel detail-panel"><div class="campaign-top"><span class="eyebrow">MATCHING</span>${badge(m.result_status||m.status)}</div><h2>${esc(m.support_title||'지원 요청 매칭')}</h2><div class="match-steps"><div class="done"><b>1</b><span>지원 요청<small>접수 완료</small></span></div><div class="${m.status?'done':''}"><b>2</b><span>기업 매칭<small>${esc(m.enterprise_name||'검토 중')}</small></span></div><div class="${m.result_status==='CONNECTED'?'done':''}"><b>3</b><span>연결 결과<small>${esc(label(m.result_status||'PENDING'))}</small></span></div></div><dl><div><dt>매칭 기업</dt><dd>${esc(m.enterprise_name||'선정 중')}</dd></div><div><dt>후보 상태</dt><dd>${esc(label(m.candidate_status||'PENDING'))}</dd></div><div><dt>연결 상태</dt><dd>${badge(m.result_status||m.status)}</dd></div><div><dt>연결일</dt><dd>${fmt(m.connected_at)}</dd></div></dl></section>`}
const slotSurfaces={owner:{kind:'개인공간',title:'원장 개인방',description:'병원 공용 공간과 분리된 원장님의 개인 업무 공간입니다.',items:['내 업무','내 활동','내 관계','내 알림']},vet:{kind:'수의사',title:'수의사방',description:'수의학 정보와 직군 네트워크를 위한 개인 공간입니다.',items:['수의학 정보','논문·증례','교육·세미나','수의사 네트워크']},assistant:{kind:'Personal AI',title:'내 비서방',description:'개인 업무와 기억을 연결할 확장 공간입니다.',items:['할 일','미완료 업무','결정·메모','후속 알림']},ownedGroups:{kind:'그룹·소모임',title:'내가 운영하는 그룹',description:'내가 만든 그룹과 그룹장으로 운영하는 공간입니다.',items:['운영 그룹','그룹 구성원','그룹장 위임']},joinedGroups:{kind:'그룹·소모임',title:'내가 참여하는 그룹',description:'가입한 그룹과 소모임을 확인하는 공간입니다.',items:['참여 그룹','그룹 소식','그룹방']},createGroup:{kind:'그룹·소모임',title:'그룹 만들기',description:'새 그룹을 만들고 참여자를 초대하는 기능입니다.',items:['그룹 정보','공개 범위','그룹방 연결']},invite:{kind:'초대',title:'초대하기',description:'조직과 공간에 함께할 사람을 초대하는 기능입니다.',items:['초대 대상','초대 상태','수락 확인']},share:{kind:'공유',title:'공유 링크',description:'캠페인과 그룹을 안전하게 공유하는 기능입니다.',items:['공유 링크','공유 상태','유입 확인']},referralCode:{kind:'추천',title:'추천 코드',description:'내 추천 코드와 사용 상태를 확인하는 기능입니다.',items:['추천 코드','사용 상태','추천 연결']},referralStatus:{kind:'추천',title:'추천 현황',description:'내 추천 활동과 연결 결과를 확인하는 기능입니다.',items:['추천 건수','연결 상태','최근 추천']},referralLineage:{kind:'추천',title:'추천 계보',description:'직접 추천과 이어진 추천 관계를 확인하는 기능입니다.',items:['직접 추천','추천 경로','연결 계보']}};
function slotCard(key,icon){const s=slotSurfaces[key];return `<button class="space-card slot" data-slot="${esc(key)}"><span class="space-icon">${esc(icon)}</span><span class="space-copy"><small>${esc(s.kind)}</small><b>${esc(s.title)}</b><em>${esc(s.description)}</em></span><span class="slot-badge">준비 중</span><i>›</i></button>`}
function friendlyRoom(room){const map={HOSPITAL_PRIVATE:['병','병원방'],VET_PRIVATE:['수','수의사방'],ENTERPRISE_PRIVATE:['기','기업방'],GUARDIAN_PRIVATE:['보','보호자방'],STUDENT_PRIVATE:['학','수의대생방'],GROUP_ROOM:['그','그룹방']};return map[room.room_type]||['공','참여 공간']}
function membershipCard(room){const [icon,name]=friendlyRoom(room);const hospital=room.room_type==='HOSPITAL_PRIVATE';return `<button class="space-card actual" ${hospital?`data-room="${esc(room.id)}"`:`data-space-room="${esc(room.id)}"`}><span class="space-icon">${icon}</span><span class="space-copy"><small>참여 중</small><b>${esc(hospital?(primaryHospital()?.name||name):name)}</b><em>${esc(label(room.membership_role))} · ${esc(label(room.status))}</em></span><span class="now-badge">이용 가능</span><i>›</i></button>`}
function spacePage(){const rooms=state.me.rooms||[];const hospital=primaryHospital();const operated=rooms.filter(r=>r.membership_role==='OWNER');return `${pageTitle('내 공간','한 계정에 연결된 역할과 공간을 한곳에서 확인하세요.')}<section class="space-summary"><div><span class="eyebrow">내 역할</span><h2>${esc((state.me.roles||[]).map(label).join(' · ')||'회원')}</h2><p>로그아웃하지 않고 연결된 공간 사이를 이동할 수 있습니다.</p></div><div><strong>${rooms.length}</strong><span>참여 공간</span></div></section><section class="space-section"><div class="section-head"><div><h2>내 개인공간</h2><p>나의 역할을 중심으로 확장될 개인 공간입니다.</p></div></div><div class="space-list">${slotCard('owner','나')}${slotCard('vet','수')}${slotCard('assistant','AI')}</div></section><section class="space-section"><div class="section-head"><div><h2>내가 운영하는 공간</h2><p>Owner 관계가 확인된 공간입니다.</p></div></div><div class="space-list">${hospital?`<button class="space-card actual" data-page="hospital"><span class="space-icon">병</span><span class="space-copy"><small>내 병원</small><b>${esc(hospital.name)}</b><em>${esc(label(hospital.position_code||'OWNER'))} · ${esc(label(hospital.verification_status))}</em></span><span class="now-badge">이용 가능</span><i>›</i></button>`:''}${operated.filter(r=>r.room_type!=='HOSPITAL_PRIVATE').map(membershipCard).join('')}${slotCard('ownedGroups','그')}</div></section><section class="space-section"><div class="section-head"><div><h2>내가 참여하는 공간</h2><p>현재 활성 Membership으로 연결된 공간입니다.</p></div><span>${rooms.length}개</span></div>${rooms.length?`<div class="space-list">${rooms.map(membershipCard).join('')}</div>`:empty('참여 중인 공간이 없습니다.','소속이나 초대가 확인되면 이곳에 표시됩니다.')}</section><section class="space-section"><div class="section-head"><div><h2>그룹·소모임</h2><p>Canonical 구조는 준비되어 있으며 사용자 API 연결 전입니다.</p></div></div><div class="space-list compact-list">${slotCard('joinedGroups','그')}${slotCard('createGroup','＋')}</div></section><section class="space-section"><div class="section-head"><div><h2>초대·추천</h2><p>초대와 추천 관계를 확인할 확장 진입점입니다.</p></div></div><div class="space-list compact-list">${slotCard('invite','초')}${slotCard('share','링')}${slotCard('referralCode','코')}${slotCard('referralStatus','현')}${slotCard('referralLineage','계')}</div></section><div class="notice">‘준비 중’ 기능은 화면 구조만 제공하며 요청 전송이나 데이터 변경을 수행하지 않습니다.</div>`}
function slotDetail(key){const s=slotSurfaces[key];return `${pageTitle(s.title,'현재는 확장 위치만 준비된 기능입니다.','<button class="secondary" data-page="space">← 내 공간</button>')}<section class="panel slot-detail"><span class="slot-badge">V1 UI SLOT · 준비 중</span><h2>${esc(s.title)}</h2><p class="lead">${esc(s.description)}</p><div class="future-list">${s.items.map(x=>`<div><span>○</span><b>${esc(x)}</b><small>향후 API 연결 후 제공</small></div>`).join('')}</div><div class="notice">현재 화면에서는 조회·저장·초대·공유를 실행하지 않습니다.</div></section>`}
function spaceRoomDetail(room){const [,name]=friendlyRoom(room);return `${pageTitle(name,'현재 Membership으로 접근 가능한 공간입니다.','<button class="secondary" data-page="space">← 내 공간</button>')}<section class="panel detail-panel"><span class="now-badge">이용 가능</span><h2>${esc(name)}</h2><p class="lead">현재 연결된 공간과 내 참여 상태를 확인합니다. 전용 서비스 기능은 해당 UX Block에서 연결됩니다.</p><dl><div><dt>내 역할</dt><dd>${esc(label(room.membership_role))}</dd></div><div><dt>이용 상태</dt><dd>${badge(room.status)}</dd></div></dl></section>`}
function groupCard(g){return `<button class="space-card actual" data-group="${esc(g.id)}"><span class="space-icon">그</span><span class="space-copy"><small>${g.group_role==='OWNER'?'내가 운영':'참여 중'}</small><b>${esc(g.name)}</b><em>${esc(g.description||'그룹 소개가 아직 없습니다.')} · ${g.member_count}명</em></span><span class="now-badge">${esc(label(g.group_role))}</span><i>›</i></button>`}
function inviteContext(){if(!state.groupInvite&&!state.referral)return '';return `<section class="context-banner"><div><b>${state.groupInvite?'그룹 초대가 도착했습니다.':'추천 링크로 방문했습니다.'}</b><p>현재 계정으로 연결 내용을 확인하고 수락할 수 있습니다.</p></div><button class="primary" id="${state.groupInvite?'acceptGroupInvite':'acceptReferral'}">연결 수락</button></section>`}
function referralPanel(){const r=state.mySpace?.referral||{};return `<div class="referral-grid"><article class="panel referral-code"><span class="eyebrow">내 추천코드</span>${r.code?`<strong>${esc(r.code)}</strong><p>추천 링크를 공유하면 연결 관계가 자동으로 기록됩니다.</p><div class="copy-row"><input readonly value="${esc(r.link)}" aria-label="추천 링크"><button class="secondary" data-copy="${esc(r.link)}">복사</button></div>`:`<h3>추천코드 만들기</h3><p>내부 회원번호가 노출되지 않는 안전한 추천코드를 생성합니다.</p><button class="primary" id="ensureReferral">추천코드 생성</button>`}</article><article class="panel"><span class="eyebrow">추천 현황</span><div class="referral-metrics"><div><strong>${r.directCount||0}</strong><span>1차 추천</span></div><div><strong>${r.totalCount||0}</strong><span>누적 추천</span></div></div><p class="muted">나를 추천한 사람: ${esc(r.referredBy||'없음')}</p></article></div><section class="panel lineage-panel"><div class="section-head"><h2>추천 계보</h2><span>${r.totalCount||0}명</span></div>${r.tree?.length?`<div class="lineage-tree">${r.tree.map(x=>`<div style="--level:${Math.min(x.level,6)}"><span>└</span><b>${esc(x.referred_name||'회원')}</b><small>${x.level}차 추천</small></div>`).join('')}</div>`:empty('아직 추천 관계가 없습니다.','추천 링크를 공유하면 실제 연결 결과가 계보로 표시됩니다.')}</section>`}
function spacePageNow(){const rooms=state.me.rooms||[],hospital=primaryHospital(),groups=state.mySpace?.groups||[],owned=groups.filter(g=>g.group_role==='OWNER'),joined=groups.filter(g=>g.group_role!=='OWNER');return `${pageTitle('내 공간','한 계정에 연결된 역할과 공간을 한곳에서 확인하세요.')}${inviteContext()}<section class="space-summary"><div><span class="eyebrow">내 역할</span><h2>${esc((state.me.roles||[]).map(label).join(' · ')||'회원')}</h2><p>로그아웃하지 않고 연결된 공간 사이를 이동할 수 있습니다.</p></div><div><strong>${rooms.length}</strong><span>참여 공간</span></div></section><section class="space-section"><div class="section-head"><div><h2>내 개인공간</h2><p>나의 역할을 중심으로 확장될 개인 공간입니다.</p></div></div><div class="space-list">${slotCard('owner','나')}${slotCard('vet','수')}${slotCard('assistant','AI')}</div></section><section class="space-section"><div class="section-head"><div><h2>내가 운영하는 공간</h2><p>내 병원과 직접 만든 그룹을 관리합니다.</p></div></div><div class="space-list">${hospital?`<button class="space-card actual" data-page="hospital"><span class="space-icon">병</span><span class="space-copy"><small>내 병원</small><b>${esc(hospital.name)}</b><em>${esc(label(hospital.position_code||'OWNER'))} · ${esc(label(hospital.verification_status))}</em></span><span class="now-badge">이용 가능</span><i>›</i></button>`:''}${owned.map(groupCard).join('')}</div></section><section class="space-section"><div class="section-head"><div><h2>내가 참여하는 공간</h2><p>현재 활성 Membership으로 연결된 Room과 그룹입니다.</p></div><span>${rooms.length+joined.length}개</span></div>${rooms.length||joined.length?`<div class="space-list">${rooms.map(membershipCard).join('')}${joined.map(groupCard).join('')}</div>`:empty('참여 중인 공간이 없습니다.','소속이나 초대가 확인되면 이곳에 표시됩니다.')}</section><section class="space-section"><div class="section-head"><div><h2>그룹·소모임 만들기</h2><p>그룹을 만들면 그룹장과 전용 그룹방이 함께 연결됩니다.</p></div></div><section class="panel form-panel group-form"><form id="groupForm"><label>그룹명<input id="groupName" maxlength="80" placeholder="예: 재활 수의사 소모임" required></label><label>그룹 소개<textarea id="groupDescription" maxlength="500" rows="4" placeholder="그룹의 목적과 활동을 소개해 주세요"></textarea></label><button class="primary" type="submit">그룹 만들기</button></form></section></section><section class="space-section"><div class="section-head"><div><h2>초대·공유·추천</h2><p>그룹 초대와 추천 관계를 실제 링크로 연결합니다.</p></div></div>${referralPanel()}</section>`}
function groupDetailView(g){const owner=g.group_role==='OWNER';return `${pageTitle(g.name,'그룹 정보와 현재 구성원을 확인하세요.','<button class="secondary" data-page="space">← 내 공간</button>')}<section class="panel detail-panel"><div class="campaign-top"><span class="eyebrow">그룹·소모임</span>${badge(g.status)}</div><h2>${esc(g.name)}</h2><p class="lead">${esc(g.description||'그룹 소개가 아직 없습니다.')}</p><dl><div><dt>내 역할</dt><dd>${esc(label(g.group_role))}</dd></div><div><dt>구성원</dt><dd>${g.members?.length||0}명</dd></div></dl>${owner?`<div class="invite-box"><h3>그룹 초대·공유</h3><p>7일 동안 유효한 안전한 초대 링크를 만듭니다.</p><button class="primary" id="createGroupInvite" data-id="${esc(g.id)}">초대 링크 생성</button><div id="inviteResult"></div></div>`:''}<div class="member-list"><h3>그룹 구성원</h3>${(g.members||[]).map(m=>`<div><span class="avatar small-avatar">${esc((m.display_name||'회').slice(0,1))}</span><b>${esc(m.display_name||'회원')}</b>${badge(m.group_role)}</div>`).join('')}</div></section>`}
function morePage(){return `${pageTitle('더보기','병원 운영과 계정 메뉴를 확인하세요.')}<div class="more-list"><button data-page="hospital"><span>✚</span><b>내 병원</b><i>›</i></button><button data-page="matching"><span>⇄</span><b>매칭</b><i>›</i></button><button data-page="account"><span>○</span><b>내 계정</b><i>›</i></button></div>`}
function accountPage(){const hospital=primaryHospital();return `${pageTitle('내 계정','회원정보와 현재 소속을 확인합니다.')}<section class="panel account-panel"><div class="avatar">${esc((state.me.profile?.display_name||'회').slice(0,1))}</div><h2>${esc(state.me.profile?.display_name||'회원')}</h2><p>${esc(state.me.profile?.email||'')}</p><dl><div><dt>회원 상태</dt><dd>${badge(state.me.state)}</dd></div><div><dt>역할</dt><dd>${esc((state.me.roles||[]).map(label).join(', '))}</dd></div><div><dt>소속 병원</dt><dd>${esc(hospital?.name||'없음')}</dd></div><div><dt>병원 인증</dt><dd>${hospital?badge(hospital.verification_status):'-'}</dd></div></dl><button class="danger-button" id="accountLogout">로그아웃</button></section>`}
function enterpriseHome(){const d=state.enterprise,e=d?.enterprise,c=d?.campaigns||[],m=d?.matching||[];if(!e)return enterpriseMissing();const alerts=[c[0]&&`${c[0].name} 캠페인이 ${label(c[0].status)} 상태입니다.`,m[0]&&`${m[0].hospital_name||'동물병원'} 요청이 ${label(m[0].result_status||m[0].candidate_status||m[0].status)} 상태입니다.`].filter(Boolean);return `${pageTitle('기업 서비스 홈','동물병원 네트워크 캠페인과 매칭 현황을 확인하세요.')}<section class="enterprise-hero"><div><span class="eyebrow">내 기업</span><h2>${esc(e.name)}</h2><p>${esc(label(e.position_code||'기업회원'))} · ${esc(label(e.affiliation_verification))}</p></div><button class="light-button" data-page="enterprise">기업방 보기 →</button></section><div class="metrics">${metric('진행 캠페인',c.filter(x=>['OPEN','ACTIVE'].includes(x.status)).length+'건','우리 기업 캠페인','campaign')}${metric('참여 병원',c.reduce((n,x)=>n+(x.hospital_count||0),0)+'곳','캠페인 연결 병원','campaign')}${metric('병원 매칭',m.length+'건',m[0]?label(m[0].result_status||m[0].candidate_status):'새 매칭 없음','matching')}${metric('제휴 프로그램',(d.advertisements?.length||0)+(d.sponsorships?.length||0)+'건','광고·스폰서십','partnership')}</div><section class="section"><div class="section-head"><h2>해야 할 일</h2></div>${alerts.length?`<div class="alert-list">${alerts.map(x=>`<div><span>●</span>${esc(x)}</div>`).join('')}</div>`:empty('현재 확인할 새 업무가 없습니다.','새로운 캠페인 신청이나 병원 매칭이 생기면 알려드립니다.')}</section><section class="section"><div class="section-head"><h2>DoctorPet에서 할 수 있는 일</h2></div>${enterpriseServices()}</section>`}
function enterpriseMissing(){return `${pageTitle('기업 서비스','기업 소속과 기업방을 확인합니다.')}<div class="state-panel deny"><strong>인증된 기업 소속이 필요합니다.</strong><p>기업 Affiliation과 기업방 Membership이 확인되면 기업 전용 서비스를 이용할 수 있습니다.</p></div>`}
function enterpriseServices(){const services=[['동물병원 캠페인','전국 제휴 동물병원을 대상으로 제품 체험·설문·캠페인을 진행합니다.','campaign','NOW'],['병원 지원·샘플·데모','병원이 요청한 제품·샘플·의료기기 데모와 연결됩니다.','matching','NOW'],['보호자 캠페인','참여 병원을 통해 보호자 대상 혜택과 체험을 확장합니다.','','SLOT'],['광고','병원 네트워크에 맞는 광고 프로그램을 협의합니다.','','SLOT'],['공식 스폰서십','전국 병원 지원과 ESG형 공식 후원 프로그램을 준비합니다.','','SLOT']];return `<div class="service-grid">${services.map(([n,d,p,s])=>`<article class="service-card ${s==='SLOT'?'slot':''}"><span class="${s==='NOW'?'now-badge':'slot-badge'}">${s==='NOW'?'이용 가능':'상담 준비'}</span><h3>${esc(n)}</h3><p>${esc(d)}</p>${p?`<button class="secondary" data-page="${p}">확인하기</button>`:'<small>현재 온라인 접수 기능은 준비 중입니다.</small>'}</article>`).join('')}</div>`}
function enterpriseRoomPage(){const d=state.enterprise,e=d?.enterprise;if(!e)return enterpriseMissing();return `${pageTitle('기업방','우리 기업에 연결된 캠페인과 병원 네트워크 업무 공간입니다.')}<section class="enterprise-hero compact"><div><span class="eyebrow">기업 전용 공간</span><h2>${esc(e.name)}</h2><p>${esc(label(e.membership_role))} · ${esc(label(e.room_status))}</p></div>${badge(e.affiliation_verification)}</section><div class="content-grid"><section class="panel"><div class="section-head"><h2>기업 정보·소속</h2><span class="slot-badge">수정 준비 중</span></div><dl class="friendly-dl"><div><dt>기업명</dt><dd>${esc(e.name)}</dd></div><div><dt>내 직책</dt><dd>${esc(label(e.position_code||'기업회원'))}</dd></div><div><dt>소속 상태</dt><dd>${badge(e.affiliation_status)}</dd></div><div><dt>인증 상태</dt><dd>${badge(e.affiliation_verification)}</dd></div></dl></section><section class="panel"><div class="section-head"><h2>기업방 구성원</h2><span>${d.members?.length||0}명</span></div>${d.members?.length?`<div class="member-list enterprise-members">${d.members.map(m=>`<div><span class="avatar small-avatar">${esc((m.display_name||'회').slice(0,1))}</span><b>${esc(m.display_name||'기업 회원')}</b>${badge(m.membership_role)}</div>`).join('')}</div>`:empty('표시할 기업 구성원이 없습니다.')}</section></div><section class="section"><div class="section-head"><h2>기업 업무 바로가기</h2></div><div class="quick-grid"><button data-page="campaign"><b>캠페인</b><span>참여 병원과 신청 현황</span></button><button data-page="matching"><b>병원 매칭</b><span>병원 요청과 연결 결과</span></button><button data-page="partnership"><b>제휴·광고·스폰서</b><span>기업 프로그램 안내</span></button></div></section>`}
function enterpriseCampaignCard(c){return `<article class="campaign-card"><div class="campaign-top"><span class="eyebrow">${esc(label(c.campaign_type)||'동물병원 캠페인')}</span>${badge(c.status)}</div><h3>${esc(c.name)}</h3><p>${esc(c.brief?.summary||c.brief?.description||'동물병원 네트워크 캠페인입니다.')}</p><div class="campaign-stats"><span>신청 <b>${c.application_count||0}</b></span><span>참여 <b>${c.participation_count||0}</b></span><span>병원 <b>${c.hospital_count||0}</b></span></div><div class="card-actions"><button class="secondary" data-enterprise-campaign="${esc(c.id)}">상세 보기</button></div></article>`}
function enterpriseCampaignsPage(){const rows=state.enterprise?.campaigns||[];return `${pageTitle('기업 캠페인','우리 기업의 캠페인과 참여 병원 현황을 확인합니다.')}<div class="campaign-proposal"><div><b>새 병원 캠페인을 진행하고 싶으신가요?</b><p>캠페인 제안 온라인 접수는 준비 중입니다. 현재는 담당자 협의를 통해 개설합니다.</p></div><span class="slot-badge">접수 API 준비 중</span></div>${rows.length?`<div class="campaign-grid">${rows.map(enterpriseCampaignCard).join('')}</div>`:empty('현재 등록된 기업 캠페인이 없습니다.','캠페인이 개설되면 진행상태와 참여 병원을 이곳에서 확인할 수 있습니다.')}`}
function enterpriseCampaignDetail(c){const apps=(state.enterprise?.applications||[]).filter(x=>x.campaign_id===c.id);return `${pageTitle('캠페인 상세','기간, 대상과 참여 현황을 확인합니다.','<button class="secondary" data-page="campaign">← 목록</button>')}<section class="panel detail-panel"><div class="campaign-top"><span class="eyebrow">기업 캠페인</span>${badge(c.status)}</div><h2>${esc(c.name)}</h2><p class="lead">${esc(c.brief?.summary||c.brief?.description||'등록된 상세 설명이 없습니다.')}</p><dl><div><dt>진행 기간</dt><dd>${fmt(c.starts_at)} — ${c.ends_at?fmt(c.ends_at):'미정'}</dd></div><div><dt>대상</dt><dd>${esc(c.brief?.target||'제휴 동물병원')}</dd></div><div><dt>신청</dt><dd>${c.application_count||0}건</dd></div><div><dt>참여 병원</dt><dd>${c.hospital_count||0}곳</dd></div></dl></section><section class="panel campaign-hospitals"><div class="section-head"><h2>신청·참여 현황</h2><span>${apps.length}건</span></div>${apps.length?`<div class="stack">${apps.map(a=>`<article class="list-card"><span class="list-icon">병</span><span><b>${esc(a.applicant_name)}</b><small>${fmt(a.submitted_at)} · ${esc(label(a.status))}</small></span>${badge(a.participation_status||a.status)}</article>`).join('')}</div>`:empty('아직 신청한 병원이 없습니다.')}</section>`}
function enterpriseMatchingPage(){const rows=state.enterprise?.matching||[];return `${pageTitle('병원 요청·매칭','우리 기업 후보로 연결된 병원 요청만 표시합니다.')}<div class="notice">병원 내부정보와 보호자 개인정보는 표시하지 않습니다. 수락·거절 Action은 운영자 연결 후 제공됩니다.</div>${rows.length?`<div class="matching-list enterprise-match-list">${rows.map(r=>`<button class="matching-card" data-enterprise-match="${esc(r.id)}"><span class="match-flow"><i>병원 요청</i><em></em><i>기업 연결</i></span><span class="match-copy"><b>${esc(r.support_title||label(r.request_type))}</b><small>${esc(r.hospital_name||'제휴 동물병원')} · ${esc(r.region_code||'지역 정보 없음')} · ${fmt(r.requested_at)}</small></span>${badge(r.result_status||r.candidate_status||r.status)}<strong>›</strong></button>`).join('')}</div>`:empty('새로운 병원 매칭 결과가 없습니다.','우리 기업이 후보로 선정된 요청만 이곳에 표시됩니다.')}`}
function enterpriseMatchDetail(r){return `${pageTitle('병원 매칭 상세','허용된 범위의 요청과 연결상태입니다.','<button class="secondary" data-page="matching">← 목록</button>')}<section class="panel detail-panel"><div class="campaign-top"><span class="eyebrow">${esc(label(r.request_type))}</span>${badge(r.result_status||r.candidate_status||r.status)}</div><h2>${esc(r.support_title||'병원 지원 요청')}</h2><dl><div><dt>요청 병원</dt><dd>${esc(r.hospital_name||'제휴 동물병원')}</dd></div><div><dt>지역</dt><dd>${esc(r.region_code||'정보 없음')}</dd></div><div><dt>요청일</dt><dd>${fmt(r.requested_at)}</dd></div><div><dt>연결 상태</dt><dd>${esc(label(r.result_status||r.candidate_status||r.status))}</dd></div></dl><div class="notice">기업의 직접 수락·거절·제안 기능은 현재 API가 없어 표시하지 않습니다.</div></section>`}
function partnershipPage(){return `${pageTitle('제휴·광고·스폰서','DoctorPet 병원 네트워크와 함께할 수 있는 기업 프로그램입니다.')} ${enterpriseServices()}<div class="content-grid partnership-status"><section class="panel"><div class="section-head"><h2>광고 현황</h2><span>${state.enterprise?.advertisements?.length||0}건</span></div>${state.enterprise?.advertisements?.length?state.enterprise.advertisements.map(x=>`<div class="status-row"><b>${esc(x.name)}</b>${badge(x.status)}</div>`).join(''):empty('진행 중인 광고가 없습니다.','온라인 광고 제안 접수는 준비 중입니다.')}</section><section class="panel"><div class="section-head"><h2>스폰서십 현황</h2><span>${state.enterprise?.sponsorships?.length||0}건</span></div>${state.enterprise?.sponsorships?.length?state.enterprise.sponsorships.map(x=>`<div class="status-row"><b>${esc(x.name)}</b>${badge(x.status)}</div>`).join(''):empty('진행 중인 스폰서십이 없습니다.','공식 스폰서십 상담 접수는 준비 중입니다.')}</section></div>`}
function enterpriseAccountPage(){const e=state.enterprise?.enterprise;return `${pageTitle('내 계정','회원정보와 기업 소속을 확인합니다.')}<section class="panel account-panel"><div class="avatar">${esc((state.me.profile?.display_name||'회').slice(0,1))}</div><h2>${esc(state.me.profile?.display_name||'기업 회원')}</h2><p>${esc(state.me.profile?.email||'')}</p><dl><div><dt>회원 상태</dt><dd>${badge(state.me.state)}</dd></div><div><dt>역할</dt><dd>기업회원</dd></div><div><dt>소속 기업</dt><dd>${esc(e?.name||'확인 필요')}</dd></div><div><dt>기업 인증</dt><dd>${e?badge(e.affiliation_verification):'-'}</dd></div></dl><button class="danger-button" id="accountLogout">로그아웃</button></section>`}
function enterpriseSpacePage(){const e=state.enterprise?.enterprise,groups=state.mySpace?.groups||[];return `${pageTitle('내 공간','기업방과 내가 참여하는 공간을 한 계정에서 이동합니다.')}<section class="space-summary"><div><span class="eyebrow">현재 Context</span><h2>${esc(e?.name||'기업 회원')}</h2><p>기업방·그룹·다른 역할 공간을 로그아웃 없이 이동합니다.</p></div><div><strong>${(state.me.rooms||[]).length+groups.length}</strong><span>참여 공간</span></div></section><section class="space-section"><div class="section-head"><div><h2>기업 공간</h2><p>인증된 기업 소속과 Membership으로 연결됩니다.</p></div></div><div class="space-list">${e?`<button class="space-card actual" data-page="enterprise"><span class="space-icon">기</span><span class="space-copy"><small>내 기업</small><b>${esc(e.name)}</b><em>${esc(label(e.membership_role))} · ${esc(label(e.room_status))}</em></span><span class="now-badge">이용 가능</span><i>›</i></button>`:''}</div></section><section class="space-section"><div class="section-head"><div><h2>그룹·소모임</h2><p>UX-2에서 연결된 실제 그룹입니다.</p></div></div>${groups.length?`<div class="space-list">${groups.map(groupCard).join('')}</div>`:empty('참여 중인 그룹이 없습니다.')}</section>${isHospitalUser()?'<div class="notice">상단의 공간 전환 버튼으로 병원 Context로 이동할 수 있습니다.</div>':''}`}
function enterpriseContent(){if(state.detail?.type==='enterpriseCampaign')return enterpriseCampaignDetail(state.detail.data);if(state.detail?.type==='enterpriseMatch')return enterpriseMatchDetail(state.detail.data);if(state.detail?.type==='group')return groupDetailView(state.detail.data);if(state.page==='home')return enterpriseHome();if(state.page==='enterprise')return enterpriseRoomPage();if(state.page==='campaign')return enterpriseCampaignsPage();if(state.page==='matching')return enterpriseMatchingPage();if(state.page==='partnership')return partnershipPage();if(state.page==='space')return enterpriseSpacePage();if(state.page==='account')return enterpriseAccountPage();if(state.page==='more')return `<div class="more-list"><button data-page="partnership"><span>◇</span><b>제휴·광고·스폰서</b><i>›</i></button><button data-page="account"><span>○</span><b>내 계정</b><i>›</i></button></div>`;return enterpriseHome()}
function legacyTable(rows,cols){return !rows?.length?empty('표시할 데이터가 없습니다.'): `<div class="table-wrap"><table><thead><tr>${cols.map(x=>`<th>${esc(x)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${cols.map(x=>`<td>${esc(typeof r[x]==='object'?JSON.stringify(r[x]):r[x])}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
async function legacyPage(kind){try{const d=kind==='admin'?await api('/admin/dashboard'):state.overview||await api('/overview');if(kind==='admin')return `<section class="hospital-hero"><div><h2>관리자 대시보드</h2><p>Scope가 확인된 ADMIN 전용</p></div></section><div class="metrics">${Object.entries(d.kpi).map(([k,v])=>metric(k,v,'')).join('')}</div><section class="panel">${legacyTable(d.persons,['display_name','email','status','state'])}${legacyTable(d.hospitals,['name','status','verification_status'])}${legacyTable(d.enterprises,['name','status','verification_status'])}${legacyTable(d.agreements,['agreement_type','status','signed_at'])}${legacyTable(d.acquisition,['source_type','source_key','channel','occurred_at'])}${legacyTable(d.reconciliation,['status','discrepancy','created_at'])}</section>`;if(kind==='campaign')return campaignsPage();if(kind==='support')return supportPage();if(kind==='matching')return matchingPage();return `${pageTitle(kind==='hospital'?'병원방':'기업방','허용된 Affiliation과 Room만 표시됩니다.')}<section class="panel">${legacyTable(state.me.affiliations,['name','organization_type','position_code','status'])}${legacyTable(state.me.rooms,['room_type','membership_role','status'])}</section>`}catch(x){return errorView(x)}}
function hospitalContent(){if(state.detail?.type==='room')return roomDetailView(state.detail.data);if(state.detail?.type==='spaceRoom')return spaceRoomDetail(state.detail.data);if(state.detail?.type==='group')return groupDetailView(state.detail.data);if(state.detail?.type==='slot')return slotDetail(state.detail.key);if(state.detail?.type==='campaign')return campaignDetail(state.detail.data);if(state.detail?.type==='support')return supportDetail(state.detail.data);if(state.detail?.type==='matching')return matchingDetail(state.detail.data);if(state.page==='home')return hospitalHome();if(state.page==='hospital')return hospitalPage();if(state.page==='campaign')return campaignsPage();if(state.page==='support')return supportPage();if(state.page==='matching')return matchingPage();if(state.page==='space')return spacePageNow();if(state.page==='account')return accountPage();if(state.page==='more')return morePage();return hospitalHome()}
async function render(override){const root=$('#app');if(!state.session){root.innerHTML=authView();$('#login').onsubmit=login;$('#signup').onsubmit=signup;return}if(state.busy){root.innerHTML=shell(loading());bindShell();return}if(override){root.innerHTML=shell(override);bindShell();return}if(!state.me){root.innerHTML=shell('<div class="state-panel"><strong>회원 연결을 확인하고 있습니다.</strong></div>');bindShell();return}if(state.me.state!=='ACTIVE'){root.innerHTML=shell(`<section class="panel activation"><h1>회원 활성화가 필요합니다.</h1><p>초대 승인을 완료하면 서비스를 이용할 수 있습니다.</p><div id="msg"></div><button id="activate" class="primary" ${state.invite?'':'disabled'}>ACTIVE 전환</button></section>`);bindShell();if($('#activate'))$('#activate').onclick=activate;return}let content=isEnterpriseContext()?enterpriseContent():isHospitalUser()?hospitalContent():await legacyPage(state.page);root.innerHTML=shell(content);bindShell();bindPage()}
function bindShell(){document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{state.page=b.dataset.page;state.detail=null;render()});document.querySelector('[data-retry]')?.addEventListener('click',load);$('#contextSwitch')?.addEventListener('click',()=>{state.context=isEnterpriseContext()?'hospital':'enterprise';sessionStorage.setItem('dp_context',state.context);state.page='home';state.detail=null;render()})}
function bindPage(){document.querySelectorAll('[data-room]').forEach(b=>b.onclick=()=>openRoom(b.dataset.room,'room'));document.querySelectorAll('[data-space-room]').forEach(b=>b.onclick=()=>openRoom(b.dataset.spaceRoom,'spaceRoom'));document.querySelectorAll('[data-slot]').forEach(b=>b.onclick=()=>{state.detail={type:'slot',key:b.dataset.slot};render()});document.querySelectorAll('[data-group]').forEach(b=>b.onclick=()=>openGroup(b.dataset.group));document.querySelectorAll('[data-copy]').forEach(b=>b.onclick=()=>copyValue(b.dataset.copy,b));document.querySelectorAll('[data-campaign]').forEach(b=>b.onclick=()=>{state.detail={type:'campaign',data:state.overview.campaigns.find(x=>x.id===b.dataset.campaign)};render()});document.querySelectorAll('[data-enterprise-campaign]').forEach(b=>b.onclick=()=>{state.detail={type:'enterpriseCampaign',data:state.enterprise.campaigns.find(x=>x.id===b.dataset.enterpriseCampaign)};render()});document.querySelectorAll('[data-enterprise-match]').forEach(b=>b.onclick=()=>{state.detail={type:'enterpriseMatch',data:state.enterprise.matching.find(x=>x.id===b.dataset.enterpriseMatch)};render()});document.querySelectorAll('[data-support]').forEach(b=>b.onclick=()=>{state.detail={type:'support',data:state.overview.support.find(x=>x.id===b.dataset.support)};render()});document.querySelectorAll('[data-matching]').forEach(b=>b.onclick=()=>{state.detail={type:'matching',data:state.overview.matching.find(x=>x.id===b.dataset.matching)};render()});$('#groupForm')?.addEventListener('submit',createGroup);$('#createGroupInvite')?.addEventListener('click',createGroupInvite);$('#ensureReferral')?.addEventListener('click',ensureReferral);$('#acceptGroupInvite')?.addEventListener('click',acceptGroupInvite);$('#acceptReferral')?.addEventListener('click',acceptReferral);$('#applyCampaign')?.addEventListener('click',applyCampaign);$('#supportForm')?.addEventListener('submit',submitSupport);$('#accountLogout')?.addEventListener('click',logout)}
async function openRoom(id,type){state.busy=true;render();try{state.detail={type,data:await api('/rooms/'+id)};state.busy=false;render()}catch(x){state.busy=false;render(errorView(x))}}
async function openGroup(id){state.busy=true;render();try{state.detail={type:'group',data:await api('/groups/'+id)};state.busy=false;render()}catch(x){state.busy=false;render(errorView(x))}}
async function copyValue(value,button){try{await navigator.clipboard.writeText(value);button.textContent='복사 완료'}catch{button.textContent='직접 선택해 복사해 주세요'}}
async function createGroup(e){e.preventDefault();try{await api('/commands',{method:'POST',idempotency:'group:'+crypto.randomUUID(),body:{commandType:'CREATE_GROUP',payload:{name:$('#groupName').value,description:$('#groupDescription').value}}});await refreshMySpace()}catch(x){alert(x.message)}}
async function createGroupInvite(){const id=$('#createGroupInvite').dataset.id;try{const result=await api('/commands',{method:'POST',idempotency:'group-invite:'+crypto.randomUUID(),body:{commandType:'CREATE_GROUP_INVITATION',payload:{groupId:id}}});const box=$('#inviteResult');box.innerHTML=`<div class="copy-row"><input readonly value="${esc(result.inviteUrl)}" aria-label="그룹 초대 링크"><button class="secondary" data-copy="${esc(result.inviteUrl)}">복사</button></div><p class="muted">이 링크는 지금 한 번만 표시됩니다. 안전하게 공유해 주세요.</p>`;box.querySelector('[data-copy]').onclick=e=>copyValue(result.inviteUrl,e.currentTarget)}catch(x){alert(x.message)}}
async function ensureReferral(){try{await api('/commands',{method:'POST',idempotency:'referral-code:'+state.me.id,body:{commandType:'ENSURE_REFERRAL_CODE',payload:{}}});await refreshMySpace()}catch(x){alert(x.message)}}
async function acceptGroupInvite(){try{await api('/commands',{method:'POST',idempotency:'accept-group:'+state.me.id+':'+state.groupInvite.slice(0,12),body:{commandType:'ACCEPT_GROUP_INVITATION',payload:{invitationToken:state.groupInvite}}});sessionStorage.removeItem('dp_group_invite');state.groupInvite='';history.replaceState({},'',location.pathname);await load()}catch(x){alert(x.message)}}
async function acceptReferral(){try{await api('/commands',{method:'POST',idempotency:'accept-ref:'+state.me.id+':'+state.referral.slice(0,12),body:{commandType:'ACCEPT_REFERRAL',payload:{referralToken:state.referral}}});sessionStorage.removeItem('dp_referral');state.referral='';history.replaceState({},'',location.pathname);await load()}catch(x){alert(x.message)}}
async function applyCampaign(){const id=$('#applyCampaign').dataset.id;if(!confirm('이 캠페인에 신청하시겠습니까?'))return;try{await api('/commands',{method:'POST',idempotency:'apply:'+state.me.id+':'+id,body:{commandType:'APPLY_CAMPAIGN',payload:{campaignId:id}}});state.detail=null;await refreshOverview()}catch(x){alert(x.message)}}
async function submitSupport(e){e.preventDefault();const hospital=primaryHospital();if(!hospital)return;try{const result=await api('/commands',{method:'POST',idempotency:'support:'+crypto.randomUUID(),body:{commandType:'CREATE_SUPPORT_REQUEST',payload:{hospitalId:hospital.hospital_id,title:$('#supportTitle').value,description:$('#supportDesc').value,requestType:$('#supportType').value}}});await refreshOverview();state.detail={type:'support',data:state.overview.support.find(x=>x.id===result.resourceId)||state.overview.support[0]};render()}catch(x){alert(x.message)}}
render();if(state.session)load();
